// ---------------------------------------------------------------------------
// Tile Flip — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'
import { Time } from '@zos/sensor'

const A = (p) => `images/${p}`

WatchFace({
  initView() {
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Tile canvas (CANVAS)
    const canvas_1 = ui.createWidget(ui.widget.CANVAS, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      show_level: ui.show_level.ONLY_NORMAL,
    })
    W.k1 = canvas_1


    // ---- user code (project.userCode) ----
    const DEBUG = true                                       // logs to the developer bridge (zeus bridge): fps while tiles are moving
    let logN = 0
    const say = (m) => { if (DEBUG) console.log('[tf ' + (++logN) + '] ' + m) }
    const cv = W.k1
    const TS = 30, COLS = 13, ROWS = 15, N = COLS * ROWS, INSET = 1
    const GAP = 0x0a0a10, DARK = 0x181822, LIT = 0xfff6e0
    const PAL = [0xb82d38, 0xc35b22, 0x227e72, 0x2659be, 0x6232b6, 0xab2956, 0x1a8252, 0x1772a7]
    const GL = { 0: '111101101101111', 1: '010110010010111', 2: '111001111100111', 3: '111001111001111', 4: '101101111001001',
      5: '111100111001111', 6: '111100111101111', 7: '111001010010010', 8: '111101111101111', 9: '111101111001111' }
    const DX = [3, 7, 3, 7], DY = [2, 2, 8, 8]                     // top-left tile of the four digits: HH on top, MM below
    const rnd = (n) => Math.floor(Math.random() * n)
    const tm = new Time()
    const R = { x1: 0, y1: 0, x2: 0, y2: 0, color: 0 }
    const rect = (x1, y1, x2, y2, col) => { R.x1 = x1; R.y1 = y1; R.x2 = x2; R.y2 = y2; R.color = col; cv.drawRect(R) }
    // ---- tile state ----
    const cur = new Array(N).fill(DARK), from = new Array(N).fill(DARK), to = new Array(N).fill(DARK)
    const t0 = new Array(N).fill(0), du = new Array(N).fill(1000), act = new Array(N).fill(0), key = new Array(N).fill(-1), lit = new Array(N).fill(0)
    let nAct = 0
    const flat = (i, col) => { const x = (i % COLS) * TS, y = Math.floor(i / COLS) * TS; rect(x, y, x + TS, y + TS, GAP); rect(x + INSET, y + INSET, x + TS - INSET, y + TS - INSET, col) }
    const pickC = (not) => { let c; do { c = PAL[rnd(PAL.length)] } while (c === not); return c }
    const flip = (i, col, delay, now, dur) => {
      if (act[i]) cur[i] = to[i]; else nAct++
      from[i] = cur[i]; to[i] = col; t0[i] = now + delay; du[i] = dur || 1000; act[i] = 1; key[i] = -1
    }
    const litFor = (str) => {
      const a = new Array(N).fill(0)
      for (let k = 0; k < 4; k++) { const g = GL[str.charAt(k)]; for (let j = 0; j < 15; j++) if (g.charAt(j) === '1') a[(DY[k] + Math.floor(j / 3)) * COLS + DX[k] + (j % 3)] = 1 }
      return a
    }
    const timeStr = () => { const h = tm.getHours(), m = tm.getMinutes(); return (h < 10 ? '0' : '') + h + (m < 10 ? '0' : '') + m }
    // the bounce: a damped spring from 0 to 1 that overshoots (about 1.2) and settles; the card angle is PI * spring
    const spring = (p) => 1 - Math.exp(-3.6 * p) * Math.cos(6.283 * 1.15 * p)
    const shade = (col, f) => (Math.floor(((col >> 16) & 255) * f) << 16) | (Math.floor(((col >> 8) & 255) * f) << 8) | Math.floor((col & 255) * f)
    const paint = (i, now) => {
      const p = (now - t0[i]) / du[i]
      if (p < 0) return
      if (p >= 1) { flat(i, to[i]); cur[i] = to[i]; act[i] = 0; nAct--; return }
      const th = Math.PI * spring(p), c = Math.cos(th), a = Math.abs(c)
      const h = Math.max(1, Math.round((TS - 2 * INSET) * a)), sh = Math.round(a * 6), k = h * 8 + sh + (th < Math.PI / 2 ? 0 : 1000)
      if (k === key[i]) return
      key[i] = k
      const x = (i % COLS) * TS, y = Math.floor(i / COLS) * TS, mid = y + TS / 2, hh = Math.floor(h / 2)
      rect(x, y, x + TS, y + TS, GAP)
      rect(x + INSET, mid - hh, x + TS - INSET, mid - hh + h, shade(th < Math.PI / 2 ? from[i] : to[i], 0.55 + 0.45 * sh / 6))
    }
    // ---- what makes tiles flip ----
    const wave = (ox, oy, now, fresh, dir) => {                  // a wave out from tile (ox, oy): every tile flips to a new colour, the lit ones flip and stay lit
      for (let i = 0; i < N; i++) {
        const c = i % COLS, r = Math.floor(i / COLS), d = Math.sqrt((c - ox) * (c - ox) + (r - oy) * (r - oy))
        if (dir) flip(i, lit[i] ? LIT : pickC(fresh ? 0 : cur[i]), (dir > 0 ? r : ROWS - 1 - r) * ROW_MS, now, 600)
        else flip(i, lit[i] ? LIT : pickC(fresh ? 0 : cur[i]), d * 240, now, 850)
      }
    }
    const ROW_MS = 160                                       // a row starts this long after the one before it: with a 600 ms flip only about 4 rows (50 tiles) move at once
    const tapFlips = (ox, oy, now) => {                    // a tap flips only the few tiles around the finger (the tile itself and its close neighbours), nearest first
      for (let i = 0; i < N; i++) {
        const c = i % COLS, r = Math.floor(i / COLS), d = Math.sqrt((c - ox) * (c - ox) + (r - oy) * (r - oy))
        if (d <= 1.5) flip(i, lit[i] ? LIT : pickC(cur[i]), d * 90, now, 900)
      }
    }
    let lastStr = '', nextRand = 0, sweepDir = 1
    const minuteChange = (str, now) => {
      const nl = litFor(str)
      for (let i = 0; i < N; i++) if (nl[i] !== lit[i]) flip(i, nl[i] ? LIT : pickC(0), (i % COLS) * 30 + rnd(80), now, 900)
      lit.splice(0, N, ...nl)
    }
    const randomFlips = (now) => {
      const n = 3 + rnd(4)
      for (let k = 0; k < n; k++) { const i = rnd(N); if (!lit[i] && !act[i]) flip(i, pickC(cur[i]), rnd(350), now, 900) }
    }
    // ---- loop ----
    let timer = null, fFrames = 0, fT0 = 0, fPeak = 0
    const tick = () => {
      timer = null
      const now = Date.now()
      try {
        const s = timeStr()
        if (s !== lastStr) { const first = lastStr === ''; lastStr = s; if (!first) minuteChange(s, now) }
        if (now >= nextRand) { randomFlips(now); nextRand = now + 2200 + rnd(2400) }
        if (nAct > 0) {
          if (fFrames === 0) { fT0 = now; fPeak = 0 }
          if (nAct > fPeak) fPeak = nAct
          for (let i = 0; i < N; i++) if (act[i]) paint(i, now)
          fFrames++
        } else if (fFrames > 0) { const ms = Math.max(1, now - fT0); say('burst: ' + fFrames + ' frames in ' + ms + ' ms = ' + Math.round(fFrames * 1000 / ms) + ' fps avg, peak ' + fPeak + ' tiles moving'); fFrames = 0 }
        if (DEBUG && fFrames > 0 && fFrames % 30 === 0) say(nAct + ' tiles in flight (incl. waiting), ' + Math.round(fFrames * 1000 / Math.max(1, now - fT0)) + ' fps so far')
      } catch (e) { say('draw: ' + e); return }
      timer = setTimeout(tick, nAct > 0 ? Math.max(0, 33 - (Date.now() - now)) : 150)
    }
    // pause / resume: the notification shade also pauses the face, so a short absence only carries on; a longer one (a real wake-up) sends a new wave
    const WAKE_GAP = 8000
    let pausedAt = 0, startedAt = 0
    const stop = () => { if (timer) { try { clearTimeout(timer) } catch (e) {} timer = null } }
    const start = (fresh) => {
      stop(); startedAt = Date.now()
      const now = startedAt
      lastStr = timeStr(); lit.splice(0, N, ...litFor(lastStr))
      if (fresh) { rect(0, 0, 390, 450, GAP); for (let i = 0; i < N; i++) { cur[i] = DARK; act[i] = 0; flat(i, DARK) } nAct = 0 }
      wave(6, 7, now, fresh, sweepDir); sweepDir = -sweepDir     // top to bottom, next wake bottom to top, and so on
      nextRand = now + 3500
      tick()
    }
    const onTap = (info) => {
      const now = Date.now(), ox = info && info.x != null ? Math.floor(info.x / TS) : 6, oy = info && info.y != null ? Math.floor(info.y / TS) : 7
      tapFlips(ox, oy, now); if (!timer) tick()
    }
    try { cv.addEventListener(ui.event.CLICK_UP, onTap) } catch (e) { say('tap: ' + e) }
    const onPause = () => { if (Date.now() - startedAt < 1500) return; pausedAt = Date.now(); stop() }   // switching faces: the watch pauses and resumes the new face right after it loads, so a pause that early must not stop the loop
    const onResume = () => {
      const n = Date.now()
      if (n - startedAt < 1500) return                       // the watch also calls resume once when the face loads
      say('resume after ' + (n - pausedAt) + ' ms' + (n - pausedAt >= WAKE_GAP ? ': wave' : ': carry on'))
      if (n - pausedAt >= WAKE_GAP) { start(false); return }
      tick()
    }
    ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: onPause, resume_call: onResume })
    start(true)

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
